   [224]={next_id=225, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="饭后，琳梅尔引着你们往二楼走，指尖点了点走廊尽头的房间。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="88", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [225]={next_id=226, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="小姐，您的房间我已经打扫干净了，被褥和沙发都是新的。", msg_color="", msg_size=0, talker="琳梅尔", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [226]={next_id=227, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="链尉官先生……既然和您是未婚夫妇，就住一间房方便些。", msg_color="", msg_size=0, talker="琳梅尔", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [227]={next_id=228, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="说完，她就笑着下了二楼，留下你和烁曦站在门口。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [228]={next_id=229, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="看到烁曦瞬间红透了的脸，你知道，作为“恋爱情侣”最难的一场戏来了。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [229]={next_id=230, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……如果你觉得不方便，我可以去睡客厅沙发，或者让琳梅尔阿姨给我打个地铺。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [230]={next_id=231, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……不用，没关系。", msg_color="", msg_size=0, talker="烁曦", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4106", 0, 0, 36.5, 184.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [231]={next_id=232, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="既然说好了要演得真实，要是分开住，肯定会让琳梅尔阿姨怀疑……", msg_color="", msg_size=0, talker="烁曦", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4106", 0, 0, 36.5, 184.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [232]={next_id=233, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她深吸一口气，终于拧开了门把手，推门时还特意错开了半步，给你让位置。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [233]={next_id=234, abreast_id={}, pType =1, cg_type =5, dialog=0, msg="黑屏转场", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="arts/storyPrefab/prefab/common/prefab/StoryMask.prefab", runTalkTime =1000, destoryTime =3000, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [234]={next_id=235, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="房间里很整洁，靠窗的书桌上摆着不少旧书，书脊上写着“骑士小说”，显然是她小时候的读物。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [235]={next_id=236, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="最显眼的是那张和房间格格不入的双人床，铺着浅粉色的床单，上面还叠着纹着康斯坦丁家族代表花卉的被子。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
